      "id": "modern-c05-l20-p01-015",
      "title": "本部と総会の議決方式",
      "body": [
        "まず国連の本部はアメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューヨーク</strong></span>に置かれ、<strong class=\"source-bold\">全加盟国（原加盟国は51カ国）が参加</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">総会</strong></span>は、議決方式が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">多数決制</strong></span>に変わったんだ。さすがに全会一致は難しいからね。"
      ],
      "plainBody": [
        "まず国連の本部はアメリカのニューヨークに置かれ、全加盟国（原加盟国は51カ国）が参加する総会は、議決方式が多数決制に変わったんだ。さすがに全会一致は難しいからね。"
      ],
