      "id": "modern-c05-l20-p01-018",
      "title": "五大国一致と拒否権",
      "body": [
        "また、<strong class=\"source-bold\">国際連盟が大国（米・独・ソ連）の不参加で弱くなった</strong>反省から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">五大国一致の原則</strong></span>がとられ、<strong class=\"source-bold\">安全保障理事会</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">常任理事国</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・仏・ソ連・中国</strong></span>）は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">拒否権</strong></span>を持っているよ。"
      ],
