      "title": "設立当初と後年の代表権",
      "body": [
        "あっ！ 設立当初は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華民国</strong></span>だから気をつけてね。現在はソ連の代表権を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span>が受け継ぎ、中国の代表権は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>に交替しているよ。"
      ],
