      "title": "財閥解体・農地改革・教育改革",
      "body": [
        "さらに、戦前に日本経済を支配してきた<strong class=\"source-bold\"><ruby>財閥<rt>ざいばつ</rt></ruby>の解体</strong>、地主制を解体して小作人に土地を分配する<strong class=\"source-bold\">農地改革</strong>、軍国主義的な教育を廃止して民主的な教育をおこなう<strong class=\"source-bold\">教育改革</strong>などが実施されたんだ。"
      ],
