      "id": "modern-c05-l20-p02-015",
      "title": "西欧の左派勢力とギリシア内戦",
      "body": [
        "しかも同じころ、西側の<strong class=\"source-bold\">フランス</strong>や<strong class=\"source-bold\">イタリア</strong>でも、経済の悪化から社会党や共産党が勢力を拡大していたし、イギリスの勢力圏だった<strong class=\"source-bold\">ギリシア</strong>では、右派（王党派）と左派（共産党派）の内戦が起きて<strong class=\"source-bold\">共産党の影響力が強まった</strong>。"
      ],
