      "id": "modern-c05-l20-p02-040",
      "title": "リオ協定と米州機構",
      "body": [
        " 1947年、ブラジルのリオデジャネイロで<strong class=\"source-bold\">リオ協定【</strong>米州共同防衛条約／リオデジャネイロ条約<strong class=\"source-bold\">】</strong>を結び、<strong class=\"source-bold\">ラテンアメリカを反共同盟に組み込む</strong>と、翌年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米州機構</strong></span> <strong class=\"source-bold\">【</strong>OAS<strong class=\"source-bold\">】</strong>をつくって、南北アメリカの連携を強化した。"
      ],
      "plainBody": [
        " 1947年、ブラジルのリオデジャネイロでリオ協定【米州共同防衛条約／リオデジャネイロ条約】を結び、ラテンアメリカを反共同盟に組み込むと、翌年には米州機構 【OAS】をつくって、南北アメリカの連携を強化した。"
      ],
