      "title": "戦後朝鮮の南北占領",
      "body": [
        "<strong class=\"source-bold\">東アジア</strong>でも、<strong class=\"source-bold\">朝鮮</strong>と<strong class=\"source-bold\">中国</strong>で資本主義と社会主義が対立したよ。<strong class=\"source-bold\">カイロ宣言</strong>で日本からの独立を約束されていた朝鮮は、戦後は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北緯38度線</strong></span>を境界に<strong class=\"source-bold\">南をアメリカ</strong>が、<strong class=\"source-bold\">北をソ連</strong>がそれぞれ<ruby>占領<rt>せんりょう</rt></ruby>していたんだけど、"
      ],
