      "title": "全面対決から和解ムードへ",
      "body": [
        "そして、スターリンのような「アメリカと全面対決して、資本主義世界を全滅させる」といった主張が弱まり、<strong class=\"source-bold\">「米ソ間の話し合いで、対立を緩和</strong>させたほうがいいのでは……」という考え方が出てきて、米ソの和解ムードを生んだ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">雪どけ</strong></span>」だ。"
      ],
