      "id": "modern-c05-l20-p05-020",
      "title": "巻き返しへのソ連の対抗",
      "body": [
        "アメリカがソ連に対する「巻き返し政策」を進めたから、両陣営の緊張は高まった。<strong class=\"source-bold\">西ドイツのNATO加盟に対抗</strong>して、1955年、<strong class=\"source-bold\">ソ連</strong>も東欧の軍事同盟として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構</strong></span> <strong class=\"source-bold\">【</strong>東欧8カ国友好協力相互援助条約<strong class=\"source-bold\">】</strong>をつくった。"
      ],
      "plainBody": [
        "アメリカがソ連に対する「巻き返し政策」を進めたから、両陣営の緊張は高まった。西ドイツのNATO加盟に対抗して、1955年、ソ連も東欧の軍事同盟としてワルシャワ条約機構 【東欧8カ国友好協力相互援助条約】をつくった。"
      ],
