export const sourcePages = {
  "363": "<h2>363</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">第5章</strong></span></h1>\n<h1><span data-source-color=\"white\" data-source-background=\"pink\" style=\"color:#ffffff;background-color:#f0a0a0\"><strong class=\"source-bold\">戦後の世界</strong></span></h1>",
  "364": "<h2>364</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">冷戦の展開①（1945〜1955）</span></h1>\n<p>いよいよ<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の世界</u>だよ。<ruby>未<rt>み</rt></ruby><ruby>曾有<rt>ぞう</rt></ruby>の世界大戦を経験した世界は、「もう戦争なんてしたくない！」って思っていたはずなのに、世界が真っ二つに分かれて対立する「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><ruby>冷戦<rt>れいせん</rt></ruby></u>」が始まってしまうんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><strong class=\"source-bold\">国際連合の成立と戦後処理</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">365〜368ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><strong class=\"source-bold\">冷戦の始まり</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">368〜372ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td><td><strong class=\"source-bold\">ベルリン問題と冷戦体制の形成</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">372〜375ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span></td><td><strong class=\"source-bold\">アジアでの対立激化</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">376〜379ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span></td><td><strong class=\"source-bold\">「雪どけ」と「巻き返し政策」</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">379〜382ページ</span></td></tr></tbody></table></div>\n<blockquote><p>なんで世界が真っ二つに分かれちゃったのかな？ 「冷戦」の始まりをしっかり理解してね</p></blockquote>\n<p>みんなが生まれたころにはすでに冷戦が終わっていたから、「世界が<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">資本主義陣営</strong></u>と<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">社会主義（共産主義）陣営</strong></u>に、真っ二つに分かれてた」って言っても、なかなかイメージできないかもね。第二次世界大戦が終わると、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカが経済的にも軍事的にも圧倒的な超大国</strong></u>になって、世界をリードしたんだけど、これに対抗したのが<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">世界で初めて社会主義国になったソ連</strong></u>だ。でも、第二次世界大戦が始まった時には、社会主義国ってソ連とモンゴルだけしかなかった。だから、大戦末期からスターリンは味方の国を強引に増やしていったんだ。こうして、世界は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカを中心とする資本主義陣営</strong></u>と<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ソ連を中心とする社会主義（共産主義）陣営</strong></u>に分かれてしまうんだよ。</p>\n<p>それじゃあ、冷戦体制がどうやってできたのか、順に見ていこう〜。</p>",
  "365": "<h2>365</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">国際連合の成立と戦後処理</u> 365</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <strong class=\"source-bold\">国際連合の成立と戦後処理</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 大戦を防げなかった国際連盟。国際平和機関の再建が必要だ！</strong></span></h4>\n<p>第一次世界大戦ののち、<strong class=\"source-bold\">史上初の国際平和機構</strong>として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟</strong></span>ができたよね。でも、<strong class=\"source-bold\">第二次世界大戦が防げなかった</strong>んだから、連盟がきちんと機能したとはいえない。そこで、大戦中から国際平和機関を再建しようという動きが起きたんだ。</p>\n<p>まず、米大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランクリン＝ローズヴェルト</strong></span>と英首相<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>が発表した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大西洋<ruby>憲章<rt>けんしょう</rt></ruby></strong></span>で<strong class=\"source-bold\">国際安全保障の確立</strong>を唱え、さらに1943年には<strong class=\"source-bold\">米・英・ソ連・中国</strong>の外相が「国際安全保障機構を早くつくるべき！」っていう<strong class=\"source-bold\">モスクワ宣言</strong>を発表したよ。その後、1944年に<strong class=\"source-bold\">ワシントン郊外</strong>で開かれた<strong class=\"source-bold\">ダンバートン＝オークス会議</strong>で、<strong class=\"source-bold\">4大国（米英ソ中）</strong>によって<strong class=\"source-bold\">国際連合憲章の原案</strong>がつくられ、大戦が終わる直前に開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サンフランシスコ会議</strong></span>で、<strong class=\"source-bold\">連合国50カ国</strong>によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連合憲章</strong></span>が<ruby>採択<rt>さいたく</rt></ruby>されると、<strong class=\"source-bold\">大戦終結後</strong>の1945年10月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連合</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連</strong></span>】</strong>が正式に発足したんだ。</p>\n<h3><strong class=\"source-bold\">〈国際連盟と国際連合の比較〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td>国際連盟</td><td>国際連合</td></tr><tr><td>本部</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ</strong></span>（スイス）</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューヨーク</strong></span>（アメリカ）</td></tr><tr><td>議決方式（総会）</td><td>加盟国<strong class=\"source-bold\">1国1票</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全会一致制</strong></span></td><td>加盟国<strong class=\"source-bold\">1国1票</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">多数決制</strong></span></td></tr><tr><td>常任理事国および大国の動向</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英・仏・伊・日</strong></span><br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米</strong></span>の不参加、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独・ソ連</strong></span>は排除など<br>大国の不参加で影響力が弱い</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">安全保障理事会</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">常任理事国</strong></span>は<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・仏・ソ連・中国</strong></span>（中華民国）<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">拒否権</strong></span>を持つ（<strong class=\"source-bold\">五大国一致の原則</strong>）</td></tr><tr><td><ruby>制裁<rt>せいさい</rt></ruby>方式</td><td>不明瞭（<strong class=\"source-bold\">経済制裁</strong>が中心）</td><td>経済制裁などの非軍事的措置のほかに、<strong class=\"source-bold\">国連軍</strong>による<strong class=\"source-bold\">軍事制裁</strong>も可能</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 国際連盟の反省からつくられた国際連合。何が変わったんだろう？</strong></span></h4>\n<p>じゃあ、国際連合がどんな組織なのかを見ていくよ。まず国連の本部はアメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューヨーク</strong></span>に置かれ、<strong class=\"source-bold\">全加盟国（原加盟国は51カ国）が参加</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">総会</strong></span>は、議決方式が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">多数決制</strong></span>に変わったんだ。さすがに全会一致は難しいからね。さらに、<strong class=\"source-bold\">戦争を防ぐため</strong>に設置された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">安全保障理事会</strong></span>は<strong class=\"source-bold\">総会よりも強い権限</strong>を持ってるんだ。総会は討議や<ruby>勧告<rt>かんこく</rt></ruby>しかできないけど、安全保障理事会では経済制裁や外交制裁だけじゃなく、<strong class=\"source-bold\">軍事制裁</strong>のために<strong class=\"source-bold\">国連軍</strong>を派遣できるようになった。まあ、軍隊送れば解決するってもんでもないけど。また、</p>\n<blockquote><p>上の表を見ながら、国際連盟と国際連合を比べてみよう！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "366": "<h2>366</h2>\n<blockquote><p>366 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p><strong class=\"source-bold\">国際連盟が大国（米・独・ソ連）の不参加で弱くなった</strong>反省から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">五大国一致の原則</strong></span>がとられ、<strong class=\"source-bold\">安全保障理事会</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">常任理事国</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・仏・ソ連・中国</strong></span>）は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">拒否権</strong></span>を持っているよ。あっ！ 設立当初は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華民国</strong></span>だから気をつけてね。現在はソ連の代表権を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span>が受け継ぎ、中国の代表権は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>に交替しているよ。そのほか、<strong class=\"source-bold\">経済社会理事会</strong>には多くの<strong class=\"source-bold\">専門機関</strong>が置かれて、さまざまな分野での国際協力が進められたほか、旧植民地の独立を助ける<strong class=\"source-bold\"><ruby>信託統治<rt>しんたくとうち</rt></ruby>理事会</strong>（かつての委任統治）も設置された。また、国際連盟の常設国際司法裁判所を継承した<strong class=\"source-bold\">国際司法裁判所</strong>も、オランダのハーグに設置されてるよ。そして、国連<ruby>憲章<rt>けんしょう</rt></ruby>にはなかった基本的人権の具体的な内容についても、1948年の<strong class=\"source-bold\">第3回国連総会</strong>で<ruby>採択<rt>さいたく</rt></ruby>された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界人権宣言</strong></span>で、あらゆる国家・国民の基本的人権の基準が示されたよ。</p>\n<h3><strong class=\"source-bold\">〈経済社会理事会の専門機関・総会の補助機関〉</strong></h3>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">ユネスコ【UNESCO・国連教育科学文化機関】</strong>［1946］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">国際労働機関【ILO】</strong> ……国際連盟の組織を受け継ぐ</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>労働問題に関して、各国政府と労働者の意見交換や協約<ruby>締結<rt>ていけつ</rt></ruby>などをおこなう</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">世界保健機関【WHO】</strong> ……保健衛生・保健事業の指導と調整をおこなう</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>国連食糧農業機関【FAO】 ……人びとの栄養水準の向上と農民の生活向上を図る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>国連<ruby>難民<rt>なんみん</rt></ruby>高等弁務官事務所【UNHCR】 ……戦時難民の救済をおこなう</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">国連児童基金【ユニセフ】</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>総会設立機関。発展途上国の幼児・児童の援助や救済をおこなう</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連貿易開発会議</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">UNCTAD</strong></span>】</strong>［1964〜］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>国連総会の常設機関。発展途上国の経済発展の促進と、<strong class=\"source-bold\">南北問題の解決</strong>が目的</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 大戦で崩壊した世界経済はどうやって再建するんだろう？</strong></span></h4>\n<p>第二次世界大戦で<strong class=\"source-bold\">ヨーロッパの経済的な没落</strong>は決定的になった。だって、世界の工業生産高のうちアメリカだけでほぼ6割だし、金（goldね）なんて世界の約3分の2はアメリカにあるんだもん。もはや、<strong class=\"source-bold\">戦後の世界経済をリードできる国はアメリカしかない</strong>！。そこでアメリカを中心に、大戦中の1944年に開かれた<strong class=\"source-bold\">ブレトン＝ウッズ会議</strong>で、戦後経済の再建が話し合われたんだ。</p>\n<p>この時、各国は「第一次大戦後のような混乱は、もうカンベン」って思っていた。だって、<strong class=\"source-bold\">ドイツの<ruby>賠償<rt>ばいしょう</rt></ruby>問題</strong>や<strong class=\"source-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong>などの経済混乱が第二次世界大戦の原因になったからね。戦争を防ぐには<strong class=\"source-bold\">経済の安定</strong>が何より重要だよ。そのために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際通貨基金</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">IMF</strong></span>】</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際<ruby>復興<rt>ふっこう</rt></ruby>開発銀行</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界銀行</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">IBRD</strong></span>】</strong>の設置が決まったよ。</p>\n<p><strong class=\"source-bold\">国際通貨基金</strong>とは、加盟国が経済状況に応じてお金を出し合って、<strong class=\"source-bold\">国際的に<ruby>為替<rt>かわせ</rt></ruby>や通貨の安定を図ろう！</strong>って機関だ。そして、<strong class=\"source-bold\">国際復興開発銀行</strong>は、国連のなかに銀行をつくって、<strong class=\"source-bold\">戦後復興や発展途上国への<ruby>融資<rt>ゆうし</rt></ruby></strong>をしよう！って機関だよ。戦間期にヨーロッパが<strong class=\"source-bold\">ドーズ案</strong>でアメリカの民間資本に復興を頼ったために、<strong class=\"source-bold\">世界恐慌で</strong></p>",
  "367": "<h2>367</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">国際連合の成立と戦後処理</u> 367</p></blockquote>\n<p><strong class=\"source-bold\">大打撃を受けた</strong>教訓からつくられた機関だ。とはいっても、戦争で経済が<ruby>破綻<rt>はたん</rt></ruby>した各国がお金を出せるわけがない……。結局、<strong class=\"source-bold\">資金を出せるのはアメリカ</strong>だよ。</p>\n<p>もう1つ、この会議では重要なことが決まった。それは、<strong class=\"source-bold\">戦後の通貨体制</strong>だ。大戦後の世界経済を支えられる国はアメリカしかないから、<strong class=\"source-bold\">アメリカの通貨（米ドル）が世界各国の通貨価値を保証する</strong>ことになった。まず<strong class=\"source-bold\">米ドルを金と<ruby>兌換<rt>だかん</rt></ruby>（交換）可能な<ruby>基軸<rt>きじく</rt></ruby>通貨</strong>として（米ドルは<ruby>金本位<rt>きんほんい</rt></ruby>制）、各国通貨と米ドルを<strong class=\"source-bold\"><ruby>固定相場制<rt>こていそうばせい</rt></ruby></strong>で結びつけた（各国通貨は、言うなれば「ドル本位制」）。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金・ドル本位制</strong></span>では、例えば日本だったら<strong class=\"source-bold\">「1ドル＝360円」で<ruby>為替<rt>かわせ</rt></ruby>相場を固定</strong>したから、日本円も米ドルを経由すれば金と交換できるでしょ。現在は為替相場が変わるけど、当時は固定相場制だから、アメリカの保有する金が各国の通貨価値を保証できるんだよ。</p>\n<h3><strong class=\"source-bold\">〈ブレトン＝ウッズ体制（金・ドル本位制）〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">アメリカ合衆国</strong></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">金</strong></span><br><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米ドル</strong></span></span><br><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">兌換可能（金本位制）</strong></span></td></tr><tr><td><strong class=\"source-bold\">英ポンド</strong><br><strong class=\"source-bold\">仏フラン</strong><br><strong class=\"source-bold\">日本円</strong></td><td><span data-source-color=\"green\" style=\"color:#315837\">固定相場制</span></td></tr></tbody></table></div>\n<blockquote><p>米ドルが「金1オンス（約30g）＝35ドル」だから、日本円も「1万2600円（360円×35ドル）」で、金1オンスと交換できたよ！</p></blockquote>\n<p>さらに、<strong class=\"source-bold\">世界恐慌後に各国がブロック経済を形成</strong>して世界の貿易がガタガタに崩壊したことを反省して、1947年には<strong class=\"source-bold\">自由で平等な国際貿易</strong>をおこなうために、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>GATT<rt>ガット</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>関税<rt>かんぜい</rt></ruby>と貿易に関する一般協定</strong></span>】</strong>が結ばれた。現在では、GATTが発展してWTO <strong class=\"source-bold\">【世界貿易機関】</strong>になっているよ。</p>\n<p>こうしてつくられた戦後の経済体制が「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレトン＝ウッズ体制</strong></span>」だ。自由貿易を基本に安定した世界経済をつくるのが目標だけど、実際のところは、<strong class=\"source-bold\">超大国になったアメリカ</strong>が<strong class=\"source-bold\">世界経済の<ruby>覇権<rt>はけん</rt></ruby></strong>を握るとともに、<strong class=\"source-bold\">戦後の復興を支える</strong>システムだよ。そして、アメリカが圧倒的な経済力と軍事力で世界の主導権を握る<strong class=\"source-bold\">「アメリカの平和【パクス＝アメリカーナ】」</strong>の時代になったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ドイツ・日本は軍隊を解散し、連合国の占領下に置かれた！</strong></span></h4>\n<p>続いて、<strong class=\"source-bold\">敗戦国の戦後処理</strong>について見ていこう。大戦終結後、<strong class=\"source-bold\">連合国は敗戦した<ruby>枢軸<rt>すうじく</rt></ruby>国を軍事占領</strong>し、戦後処理をおこなったよ。日本とドイツの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">軍隊は解散</strong></span>させられ、戦争指導者を<strong class=\"source-bold\">国際軍事裁判</strong>（ドイツでは<strong class=\"source-bold\">ニュルンベルク裁判</strong>、日本では<strong class=\"source-bold\">東京裁判【<ruby>極東<rt>きょくとう</rt></ruby>国際軍事裁判】</strong>）で「<ruby>人道<rt>じんどう</rt></ruby>に対する罪」として<ruby>処罰<rt>しょばつ</rt></ruby>したんだ。その後、枢軸国のうち<strong class=\"source-bold\">イタリア、ハンガリー、ルーマニア、ブルガリア、フィンランド</strong>の5カ国は1947年の<strong class=\"source-bold\">パリ<ruby>講和<rt>こうわ</rt></ruby>条約</strong>で主権を回復したんだけど、<strong class=\"source-bold\">ドイツ・日本は連合国に<ruby>占<rt>せん</rt></ruby></strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "368": "<h2>368</h2>\n<blockquote><p>368 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p><strong class=\"source-bold\"><ruby>領統治<rt>りょうとうち</rt></ruby>された</strong>ままだった。そして、さまざまな民主化がおこなわれたんだ。</p>\n<p>まず<strong class=\"source-bold\">ドイツ</strong>は、<strong class=\"source-bold\">米・英・仏・ソ連</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">4カ国による分割占領</strong></span>となり、ポーランドとの国境は<ruby>暫定<rt>ざんてい</rt></ruby>的に<strong class=\"source-bold\">「オーデル＝ナイセ線」</strong>とされた。さらにソ連の管理地域のなかにある首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン</strong></span>も、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">4カ国による分割管理</strong></span>になったんだ。そして、民主化を徹底するために、<strong class=\"source-bold\">ナチスの解党、宣伝の禁止、関係者の公職追放、政治・教育の民主化</strong>などの<strong class=\"source-bold\">非ナチ化</strong>がおこなわれた。さらに、ドイツ人の国<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア</strong></span>も同じように<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">4カ国による分割管理</strong></span>になったんだ。</p>\n<p>一方、<strong class=\"source-bold\">日本は分割されずに連合軍に占領された</strong>んだけど、連合軍とはいってもほぼ<strong class=\"source-bold\">アメリカ軍</strong>だけで、<strong class=\"source-bold\">マッカーサー</strong>を最高司令官とする<strong class=\"source-bold\">GHQ【連合国軍最高司令官総司令部</strong>／SCAP<strong class=\"source-bold\">】</strong>が統治することになった。ただ、占領の期間も<strong class=\"source-bold\">日本政府は存続</strong>していたから、マッカーサーは日本政府を通じて日本国民を統治したんだ（間接統治方式）。こうして、GHQの占領下で民主化が進み、1946年には<strong class=\"source-bold\">国民主権、<ruby>象<rt>しょう</rt></ruby><ruby>徴<rt>ちょう</rt></ruby>天皇制、平和主義、基本的人権の尊重</strong>などを定めた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本国憲法</strong></span>が公布されたよ。さらに、戦前に日本経済を支配してきた<strong class=\"source-bold\"><ruby>財閥<rt>ざいばつ</rt></ruby>の解体</strong>、地主制を解体して小作人に土地を分配する<strong class=\"source-bold\">農地改革</strong>、軍国主義的な教育を廃止して民主的な教育をおこなう<strong class=\"source-bold\">教育改革</strong>などが実施されたんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <strong class=\"source-bold\">冷戦の始まり</strong></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">冷戦の始まり</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（社会主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>チャーチル「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">鉄のカーテン</strong></span>」演説［1946］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン＝ドクトリン</strong></span>［1947.3］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>封<rt>ふう</rt></ruby>じ込め政策</strong></span>」開始</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マーシャル＝プラン</strong></span>［1947.6］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルム</strong></span>結成［1947.9］</td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア＝クーデタ</strong></span>［1948.2］</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ヨーロッパ連合条約</strong></span>［1948.3］</td><td></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルムのユーゴ除名</strong></span>［1948.6］</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西側管理地区通貨改革</strong></span>［1948.6］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン封鎖</strong></span>［1948.6〜49.5］<br><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コメコン</strong></span>創設［1949.1］</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北大西洋条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>NATO<rt>ナトー</rt></ruby></strong></span>】</strong>［1949.4］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ連邦共和国</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ドイツ</strong></span>】</strong>成立［1949.5］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ民主共和国</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東ドイツ</strong></span>】</strong>成立［1949.10］</td></tr></tbody></table></div>",
  "369": "<h2>369</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の始まり</u> 369</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ そもそも<ruby>冷戦<rt>れいせん</rt></ruby>ってなんだろう？ 東西対立って、なんの東西？</strong></span></h4>\n<p>さて、続いて<strong class=\"source-bold\">冷戦の開始</strong>について話すんだけど、そもそも「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷戦</strong></span>」っていわれても「なんじゃそりゃ」って感じかもね。そりゃ、みんなは冷戦が終わってから生まれたんだから、わからなくても当たり前だよ。</p>\n<p><strong class=\"source-bold\">ドイツ・日本の敗戦</strong>が見えてくると、連合国は<strong class=\"source-bold\">戦後の国際秩序</strong>について考え始めた。そして、大戦を通じて発言力が強くなったのは、圧倒的な経済大国・軍事大国に成長した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>と、1941〜44年の3年間、単独でドイツと戦った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>だよ。米ソ両国は<strong class=\"source-bold\">大戦中には協力</strong>していたけど、<strong class=\"source-bold\">戦後の構想は全然違う</strong>。大戦末期には、すでに両国が「勢力圏」を拡大しようとしていたから、<strong class=\"source-bold\">米英軍</strong>が攻め込んだ<strong class=\"source-bold\">西ヨーロッパは資本主義国</strong>（「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西側</strong></span>」）、<strong class=\"source-bold\">ソ連</strong>が攻め込んだ<strong class=\"source-bold\">東ヨーロッパは社会主義国</strong>（「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東側</strong></span>」・<strong class=\"source-bold\">共産圏</strong>）になった。この両者の対立が「<strong class=\"source-bold\">東西対立</strong>」だ。それから、厳密に言うと違うんだけど、入試レベルなら<strong class=\"source-bold\">「社会主義≒共産主義」</strong>と考えていいよ。そして<strong class=\"source-bold\">両陣営は勢力拡大を狙って激しく対立</strong>したけど、ヨーロッパでは実際の戦闘（こっちは“熱い戦争”と呼んだりする）が起きなかったから、<strong class=\"source-bold\">戦争が凍結された“冷たい”戦争</strong>、つまり「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷戦</strong></span>」となったんだ。</p>\n<blockquote><p>「西側」は資本主義陣営、「東側」は社会主義陣営のことだよ！ これって、ヨーロッパが基準だよね……</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連の「鉄のカーテン」に対し、アメリカは「封じ込め政策」を開始！</strong></span></h4>\n<p><strong class=\"source-bold\">ソ連</strong>の指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>は「社会主義国（ソ連の味方）を増やしたい」って思っていた。だって、戦前に社会主義だったのは<strong class=\"source-bold\">ソ連とモンゴル人民共和国</strong>の2つだけだもん。ソ連がドイツ軍を破った東ヨーロッパの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド、ブルガリア、ルーマニア、ハンガリー</strong></span>ではソ連寄りの共産主義者が<strong class=\"source-bold\">レジスタンス</strong>の中心となり、戦後は次々と<strong class=\"source-bold\">社会主義国</strong>となった。また<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア</strong></span>（以下「ユーゴ」と省略するね）では、<strong class=\"source-bold\">パルチザン闘争</strong>でドイツを破った共産党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティトー</strong></span>が政権をつくったよ。あっ、<strong class=\"source-bold\">ユーゴはソ連の力を借りずにドイツに勝った</strong>んだ！ あとで大事だから覚えといてね。こうして<strong class=\"source-bold\">東欧は社会主義国</strong>ばっかりになった。こうした社会主義体制を<strong class=\"source-bold\">人民民主主義</strong>と呼ぶよ。</p>\n<p>これを警戒した前イギリス首相の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>は、<strong class=\"source-bold\">アメリカのフルトン</strong>で「バルト海の<strong class=\"source-bold\">シュテッティン</strong>からアドリア海の<strong class=\"source-bold\">トリエステ</strong>まで、大陸を横切って“<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">鉄のカーテン</strong></span>”が降ろされた！」という演説をおこなって、<strong class=\"source-bold\">ソ連が勢力圏をつくっている</strong>と警告したよ。しかも同じころ、西側の<strong class=\"source-bold\">フランス</strong>や<strong class=\"source-bold\">イタリア</strong>でも、経済の悪化から社会党や共産党が勢力を拡大していたし、イギリスの勢力圏だった<strong class=\"source-bold\">ギリシア</strong>では、右派（王党派）と左派（共産党派）の内戦が起きて<strong class=\"source-bold\">共産党の影響力が強まった</strong>。さらに黒海から地中海へと抜けるダーダネルス・ボスフォラス海峡をめぐり、<strong class=\"source-bold\">ソ連がトルコへ</strong>の圧力を強めていたんだ。このままじゃ社会主義が拡大しちゃうよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "370": "<h2>370</h2>\n<blockquote><p>370 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p>1947年、財政的に余裕がない<strong class=\"source-bold\">イギリス</strong>が「<strong class=\"source-bold\">ギリシア・トルコから撤退</strong>する」とアメリカに伝えると、<strong class=\"source-bold\">アメリカ大統領</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン</strong></span>は「イギリスにかわって<strong class=\"source-bold\">ギリシア・トルコを経済的・軍事的に援助</strong>する」って宣言した。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン＝ドクトリン</strong></span>は、アメリカによる対ソ「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>封<rt>ふう</rt></ruby>じ込め政策</strong></span>」の始まりだよ。これは、<strong class=\"source-bold\">「イギリス・フランス・イタリア・ギリシア・トルコ」</strong>を結ぶ線の内側に<strong class=\"source-bold\">社会主義を封じ込めて</strong>、「鉄のカーテン」の西側の資本主義国を守るってことだ。</p>\n<p>さらに6月には、<strong class=\"source-bold\">国務長官</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マーシャル</strong></span>が、西ヨーロッパの<strong class=\"source-bold\">社会主義化を阻止</strong>して資本主義を守るための経済<ruby>復興<rt>ふっこう</rt></ruby>計画、いわゆる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マーシャル＝プラン</strong></span> <strong class=\"source-bold\">【ヨーロッパ経済復興援助計画】</strong>を発表した。簡単に言うと<strong class=\"source-bold\">「社会主義を排除すれば、アメリカがお金をあげる」</strong>ってことだ。こりゃ、アメリカの金持ち自慢だな……。この時、援助を受けるためにイタリアやフランスでは社会党や共産党の閣僚を追放した。そして西ヨーロッパ16カ国で<strong class=\"source-bold\">ヨーロッパ経済協力機構【OEEC】</strong>（のちのOECD <strong class=\"source-bold\">【経済協力開発機構】</strong>）を結成して、マーシャル＝プランを受け入れたんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">米</strong></td><td><strong class=\"source-bold\">英</strong><br><strong class=\"source-bold\">仏</strong><br><strong class=\"source-bold\">伊</strong><br><strong class=\"source-bold\">ギリシア</strong><br><strong class=\"source-bold\">トルコ</strong></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義</strong></span></td></tr></tbody></table></div>\n<blockquote><p>「封じ込め」のイメージはこんな感じだ！</p></blockquote>\n<p>これを見た<strong class=\"source-bold\">スターリンは怒った</strong>！ 「もはや、アメリカや資本主義陣営との和解は不可能だ」として、ヨーロッパ各国の<strong class=\"source-bold\">共産党の結束を強化</strong>するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルム</strong></span> <strong class=\"source-bold\">【共産党情報局】</strong>を結成した。ここには、<strong class=\"source-bold\">ソ連・ブルガリア・ルーマニア・ハンガリー・ポーランド・チェコスロヴァキア・ユーゴスラヴィア</strong>といった社会主義国の共産党のほかに、<strong class=\"source-bold\">西側からフランス・イタリアの共産党</strong>も加盟して、<strong class=\"source-bold\">資本主義体制を破壊</strong>して<strong class=\"source-bold\">親米政権を打倒</strong>するために団結することになったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 東欧はさまざまな社会主義を模索。西欧も同盟政策を強化！</strong></span></h4>\n<p><strong class=\"source-bold\">東ヨーロッパ諸国ではソ連の影響力が強かった</strong>けど、いきなりすべての国が共産党の一党<ruby>独裁<rt>どくさい</rt></ruby>体制になったわけじゃないよ。例えば、<strong class=\"source-bold\">チェコスロヴァキア</strong>（以下「チェコ」と省略するね）では、最初は<strong class=\"source-bold\">自由主義政党と共産党の連立政権</strong>がつくられて、少なくともマーシャル＝プランが発表される前には、<strong class=\"source-bold\">議会制民主主義が機能して</strong>いたんだ。しかし、<strong class=\"source-bold\">マーシャル＝プランの受け入れをめぐって共産党と自由主義政党が対立</strong>すると、ソ連はチェコに圧力をかけ、<strong class=\"source-bold\">マーシャル＝プランへの参加を拒否させた</strong>。これはスターリンがアメリカとの協調路線を捨てて、どんな手を使ってでも東欧をソ連の勢力圏に置くという意図が明確になった瞬間だよ。そして、警察や民兵を使って<strong class=\"source-bold\">共産党以外の閣僚が一掃</strong>され、<strong class=\"source-bold\">ベネシュ</strong>大統領も辞任して、事実上共産党の一党独裁政権ができたんだ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア＝クーデタ</strong></span>）。</p>",
  "371": "<h2>371</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の始まり</u> 371</p></blockquote>\n<h3><strong class=\"source-bold\">〈冷戦下のヨーロッパ〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ノルウェー</strong></td><td><strong class=\"source-bold\">イギリス</strong></td></tr><tr><td><strong class=\"source-bold\">オランダ</strong></td><td><strong class=\"source-bold\">ベルギー</strong></td></tr><tr><td><strong class=\"source-bold\">ルクセンブルク</strong></td><td><strong class=\"source-bold\">フランス</strong></td></tr><tr><td><strong class=\"source-bold\">ポルトガル</strong></td><td><strong class=\"source-bold\">スペイン</strong></td></tr><tr><td><strong class=\"source-bold\">西ドイツ</strong></td><td><strong class=\"source-bold\">東ドイツ</strong></td></tr><tr><td>シュテッティン</td><td>ベルリン</td></tr><tr><td><strong class=\"source-bold\">ポーランド</strong></td><td><strong class=\"source-bold\">チェコスロヴァキア</strong></td></tr><tr><td><strong class=\"source-bold\">スイス</strong></td><td><strong class=\"source-bold\">オーストリア</strong></td></tr><tr><td>トリエステ</td><td><strong class=\"source-bold\">イタリア</strong></td></tr><tr><td><strong class=\"source-bold\">ハンガリー</strong></td><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td><strong class=\"source-bold\">ユーゴスラヴィア</strong>（自主路線）</td><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td><strong class=\"source-bold\">アルバニア</strong></td><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><strong class=\"source-bold\">トルコ</strong></td><td><strong class=\"source-bold\">ソ連</strong></td></tr><tr><td><span data-source-marker=\"rectangle\" data-source-background=\"green\" style=\"display:inline-block;width:1em;height:0.6em;background-color:#859476\"></span> NATO加盟国（1955年時点）</td><td><span data-source-marker=\"rectangle\" data-source-background=\"red\" style=\"display:inline-block;width:1em;height:0.6em;background-color:#e52715\"></span> ワルシャワ条約機構加盟国</td></tr><tr><td><span data-source-marker=\"line\" data-source-color=\"brown\" style=\"display:inline-block;width:1em;border-bottom:0.25em solid #a43725\"></span> 鉄のカーテン（1946年）</td><td></td></tr></tbody></table></div>\n<p>一方、バルカン半島のユーゴでは、<strong class=\"source-bold\">対ドイツ戦争に自力で勝利</strong>した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティトー</strong></span>が、<strong class=\"source-bold\">独自の社会主義国家建設</strong>を目指した。ティトーにしてみれば「私はソ連に借りはない」ってことだね。そして独自の<strong class=\"source-bold\">バルカン連邦</strong>をつくるためにユーゴがアルバニアを<ruby>併合<rt>へいごう</rt></ruby>しようとすると、怒ったソ連がアルバニアを支援し、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルムからユーゴスラヴィアを除名</strong></span>したんだ。ただ、<strong class=\"source-bold\">ティトー</strong>はソ連の言うことを聞く気はないから、<strong class=\"source-bold\">アメリカに接近</strong>して経済的・軍事的な援助を受けることにした。以後、ユーゴはソ連とは別の社会主義モデル（<strong class=\"source-bold\">自主路線</strong>）に進むんだ。</p>\n<p>こうした動きは、西欧諸国にも影響を与えたよ。特に<strong class=\"source-bold\">チェコ＝クーデタ</strong>は<strong class=\"source-bold\">むちゃくちゃ衝撃</strong>だった！。だって、チェコは東欧で唯一、議会制民主主義になって、戦後も共産党と自由主義政党の連立政権だったからね。しかも同じころ、<strong class=\"source-bold\">イタリアで共産党が勢力を拡大</strong>していたし……。「チェコの次はイタリア、その次はどこだ？ ヨーロッパ全体が共産主義者に飲み込まれる」という一種の<strong class=\"source-bold\">反共</strong>（反共産主義）<strong class=\"source-bold\">パニック</strong>となった<strong class=\"source-bold\">英仏とベネルクス3国（オランダ・ベルギー・ルクセンブルク）</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ヨーロッパ連合条約</strong></span> <strong class=\"source-bold\">【ブリュッセル条約】</strong>を結び、ソ連と東欧諸国に対抗する軍事同盟（<strong class=\"source-bold\">反共軍事同盟</strong>）をつくったんだ。そして、イギリスはこの同盟にアメリカを招き入れようとした。これが、<strong class=\"source-bold\">のちに<ruby>NATO<rt>ナトー</rt></ruby>に発展</strong>するよ。</p>\n<p>それから、同じ時期に<strong class=\"source-bold\">アメリカがラテンアメリカで反共同盟をつくっている</strong>ことにも注目しておこう！ 1947年、ブラジルのリオデジャネイロで<strong class=\"source-bold\">リオ協定【</strong>米州共</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "372": "<h2>372</h2>\n<blockquote><p>372 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p>同防衛条約／リオデジャネイロ条約<strong class=\"source-bold\">】</strong>を結び、<strong class=\"source-bold\">ラテンアメリカを反共同盟に組み込む</strong>と、翌年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米州機構</strong></span> <strong class=\"source-bold\">【</strong>OAS<strong class=\"source-bold\">】</strong>をつくって、南北アメリカの連携を強化した。もちろん、<strong class=\"source-bold\">ラテンアメリカの共産化阻止</strong>が目的だよ！ そして、ラテンアメリカでは、多くの国で<strong class=\"source-bold\">アメリカが支援する軍事政権</strong>が成立することになる。<strong class=\"source-bold\">キューバ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バティスタ</strong></span>政権や<strong class=\"source-bold\">ニカラグア</strong>の<strong class=\"source-bold\">ソモサ</strong>政権が代表的な親米軍事政権だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <strong class=\"source-bold\">ベルリン問題と冷戦体制の形成</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ベルリン封鎖VS.大空輸作戦！ ドイツをめぐる対立は修復不可能になった</strong></span></h4>\n<p>ドイツは<strong class=\"source-bold\">米英仏ソ4カ国によって分割<ruby>占領<rt>せんりょう</rt></ruby></strong>されたけど、いずれは統一することになっていた。でも、米ソ両国の占領方針が違いすぎるよ……。<strong class=\"source-bold\">アメリカ</strong>は早いとこ<strong class=\"source-bold\">ドイツを<ruby>復興<rt>ふっこう</rt></ruby></strong>して<strong class=\"source-bold\">国際経済に復帰</strong>させ、ヨーロッパの復興をスピードアップさせたい。一方、<strong class=\"source-bold\">ソ連</strong>はドイツを<strong class=\"source-bold\">社会主義国</strong>にして、さらに戦争の<ruby>賠償<rt>ばいしょう</rt></ruby>としてドイツの工場から機械などをソ連に移動した。結局、<strong class=\"source-bold\">4国外相会談</strong>では交渉が決裂したんだ。</p>\n<h3><strong class=\"source-bold\">〈ドイツの分割占領とベルリン問題〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">イギリス管理地区</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連管理地区</strong></span></td></tr><tr><td><strong class=\"source-bold\">フランス管理地区</strong></td><td><strong class=\"source-bold\">アメリカ管理地区</strong></td></tr><tr><td><strong class=\"source-bold\">ボン</strong></td><td><strong class=\"source-bold\">ニュルンベルク</strong></td></tr><tr><td><strong class=\"source-bold\">ベルリン</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">ベルリンの4国管理</strong></td><td>西側<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span><br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">（太線）ソ連によるベルリン封鎖</strong></span></td></tr><tr><td><strong class=\"source-bold\">西側管理地区（のちの西ドイツ）</strong></td><td><strong class=\"source-bold\">東側管理地区（のちの東ドイツ）</strong></td></tr></tbody></table></div>\n<blockquote><p>ベルリン封鎖で、スターリンは西ベルリン市民を人質にしたんだよ！</p></blockquote>\n<p>1948年に入ると、まずアメリカから仕掛けたんだ。<strong class=\"source-bold\">米英仏の3国</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西側管理地区で通貨改革</strong></span>をおこない、米ドルと交換できる新通貨（西ドイツ＝マルク）を発行した。これって<strong class=\"source-bold\">西側の占領地区だけ統合</strong>して、<strong class=\"source-bold\">新しいドイツ国家をつくる準備</strong>だよ。ソ連も対抗して東側で新通貨を発行したけれど、もはやドイツ全体を統合するのはムリだ。さらに大問題なのは、ソ連占領地域のなかにある「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ベルリン</strong></span>」。アメリカは<strong class=\"source-bold\">西ベルリンでも通貨改革をやって</strong>、経済力をベルリン市民に見せつけた。まだ東西ベルリンは自由に行き来できたから、東ベルリン市民のなかには「アメリカのほうがスゴイ！ 資本主義のほうがいい！」と、<strong class=\"source-bold\">西へ移住</strong>する人も出て</p>",
  "373": "<h2>373</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ベルリン問題と冷戦体制の形成</u> 373</p></blockquote>\n<p>きたんだ。</p>\n<p>対する<strong class=\"source-bold\">スターリン</strong>も黙ってはいない！ <strong class=\"source-bold\">通貨改革への<ruby>報復<rt>ほうふく</rt></ruby></strong>として、<strong class=\"source-bold\">西ベルリンにつながる鉄道・道路・運河などの交通を武力で<ruby>封鎖<rt>ふうさ</rt></ruby></strong>し、<strong class=\"source-bold\">電力の供給もストップ</strong>！ 西ベルリンを「陸の孤島」にしたんだ。「食料も電力もなければ、西ベルリン市民は<ruby>飢<rt>う</rt></ruby>え<ruby>死<rt>じ</rt></ruby>にだ。アメリカめ、思い知れ！」ってね。</p>\n<p><strong class=\"source-bold\">ソ連</strong>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン封鎖</strong></span>は、世界中を<ruby>震撼<rt>しんかん</rt></ruby>させた。下手すれば米ソ戦争が始まり、いきなり第三次世界大戦じゃないか！ でも、アメリカ大統領<strong class=\"source-bold\">トルーマン</strong>は、「西ベルリン市民は絶対助ける」と宣言して、<strong class=\"source-bold\">米軍の輸送機を使って西ベルリンに生活物資を運び入れる</strong>ことにした。もし輸送機が<ruby>撃墜<rt>げきつい</rt></ruby>されたら……即開戦だ。しかし、トルーマンの決意は固い！ こうしてアメリカは<strong class=\"source-bold\">大空輸作戦</strong>を始め、封鎖が解除されるまでの1年間で約28万便もの輸送機を西ベルリンへと飛ばした。これで、ドイツをめぐる対立は、話し合いじゃ解決できなくなったよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span> <strong class=\"source-bold\">の分かれ目 冷戦の構造を確認しよう！</strong></h3>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西側</strong></span>……<strong class=\"source-bold\">アメリカを中心とする資本主義陣営（自由主義）</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>政治：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン＝ドクトリン</strong></span>［1947.3］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ギリシア・トルコへの経済・軍事援助</strong>を表明 <span data-source-color=\"green\" style=\"color:#315837\">➡</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>封<rt>ふう</rt></ruby>じ込め政策</strong></span>」開始</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>経済：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マーシャル＝プラン</strong></span> <strong class=\"source-bold\">【ヨーロッパ経済復興援助計画】</strong>［1947.6］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>西ヨーロッパの共産化阻止のため、<strong class=\"source-bold\">アメリカが復興資金を援助</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>軍事：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北大西洋条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">NATO</strong></span>】</strong>［1949.4］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>アメリカを中心に、カナダも含めた西側12カ国で結成した<strong class=\"source-bold\">反共軍事同盟</strong></p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東側</strong></span>……<strong class=\"source-bold\">ソ連を中心とする社会主義陣営（共産圏）</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>政治：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルム</strong></span> <strong class=\"source-bold\">【共産党情報局】</strong>［1947.9］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>各国共産党の結束を強化するための情報機関。西側（<strong class=\"source-bold\">仏・伊</strong>）の共産党も加盟</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>経済：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コメコン</strong></span> <strong class=\"source-bold\">【経済相互援助会議／COMECON】</strong>［1949.1］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>マーシャル＝プランに対抗した<strong class=\"source-bold\">ソ連中心の経済協力機構</strong>。実態はソ連が東欧を<ruby>搾取<rt>さくしゅ</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>軍事：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構</strong></span> <strong class=\"source-bold\">【東欧8カ国友好協力相互援助条約】</strong>［1955.5］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ドイツのNATO加盟</strong></span>と再軍備に対抗した<strong class=\"source-bold\">東側陣営の軍事同盟</strong></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アメリカがついに軍事同盟に加わり、ドイツは東西に分断された！</strong></span></h4>\n<p>外交交渉が不可能になると、<strong class=\"source-bold\">米ソ両国はそれぞれの陣営の結束を強化</strong>したよ。1949年1月、<strong class=\"source-bold\">ソ連</strong>は東欧への支配を強化するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コメコン</strong></span> <strong class=\"source-bold\">【経済相互援助会議】</strong>をつくった。これは<strong class=\"source-bold\">マーシャル＝プランに対抗</strong>した経済協力機関なんだけど、実態は、東欧諸国に農業・工業などの産業を割り当てて、<strong class=\"source-bold\">ソ連が東欧から搾取</strong>するんだよ。これで、東欧諸国は絶対にソ連よりも豊かにはなれなくなった。あっ、す</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "374": "<h2>374</h2>\n<blockquote><p>374 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p>でに<strong class=\"source-bold\">自主路線を歩んでいるユーゴスラヴィアは入っていない</strong>よ！</p>\n<p>対する<strong class=\"source-bold\">アメリカ</strong>は孤立主義を完全に捨てて、<strong class=\"source-bold\">西ヨーロッパとの軍事同盟を強化</strong>するため、1949年4月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北大西洋条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>NATO<rt>ナトー</rt></ruby></strong></span>】</strong>をつくった。こうして西側は、<strong class=\"source-bold\">アメリカの圧倒的な経済力と軍事力</strong>を背景に、東側陣営との対決姿勢を強めたんだ。</p>\n<p>そして、<strong class=\"source-bold\">ドイツは分断されて独立</strong>することになった。まず米英仏3国は、1949年5月に基本法（憲法）を制定させて、<ruby>占領<rt>せんりょう</rt></ruby>状態のままの西側に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ連邦共和国</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ドイツ</strong></span>】</strong>をつくった。この時、<ruby>暫定<rt>ざんてい</rt></ruby>首都とされたのが<strong class=\"source-bold\">ボン</strong>。ていうか、ボンって知ってる？ たまに文化史で、作曲家<strong class=\"source-bold\">ベートーヴェンの出身地</strong>って出てくるけど……あまり有名じゃないよね。暫定っていうのは「今はボンだけど、<strong class=\"source-bold\">将来ドイツを統一した時に、首都はベルリンにする</strong>」っていう意味だ。そして西ドイツでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アデナウアー</strong></span>が首相となり、1950年代には<strong class=\"source-bold\">「奇跡の経済<ruby>復興<rt>ふっこう</rt></ruby>」</strong>を実現したよ。</p>\n<p>西ドイツが建国されるとベルリン<ruby>封鎖<rt>ふうさ</rt></ruby>の意味がなくなり、ソ連は1949年5月に封鎖を解除し、同じ年の10月には東側に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ民主共和国</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東ドイツ</strong></span>】</strong>をつくったよ。首都は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン</strong></span>だ。東ドイツは<strong class=\"source-bold\">共産党と社会民主党が合同</strong>した<strong class=\"source-bold\">社会主義統一党</strong>の<strong class=\"source-bold\">一党<ruby>独裁<rt>どくさい</rt></ruby>体制</strong>になり、急激に<strong class=\"source-bold\">ソ連型の社会主義国家建設</strong>が進んだから、「いよいよ自由がなくなる」と思った人は、西側に脱出し始めた。皮肉なもんで、どんどん国境の閉鎖が進み、<strong class=\"source-bold\">国境を行き来できるのは封鎖が解除されたベルリンだけ</strong>になったんだ。こんなふうに、ヨーロッパでは戦争こそ起きなかったものの、対立はどんどん激しくなっていったよ。じゃあ、同じ時期の各国の国内問題も見ておこう！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>冷戦<rt>れいせん</rt></ruby>が始まって、西側の各国では何が起きたんだろう？</strong></span></h4>\n<p><strong class=\"source-bold\">アメリカ合衆国</strong>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン</strong></span>大統領が「フェアディール」と呼ばれる福祉政策を進めたんだけど、「社会福祉を拡大すると労働者の力が強くなって、社会主義が広がるのでは……」と警戒されちゃった。そして、アメリカではかえって<strong class=\"source-bold\">社会主義への反発が強まり</strong>、国家安全保障法で<strong class=\"source-bold\">中央情報局【CIA】</strong>や国家軍事機構（のちの国防総省）などが設置されたほか、ワグナー法で保障した労働者の権利を大幅に制限する<strong class=\"source-bold\">タフト・ハートレー法</strong>がつくられ、労働運動が<ruby>弾圧<rt>だんあつ</rt></ruby>されたんだ。さらに1950年代に入ると、共和党の上院議員<strong class=\"source-bold\">マッカーシー</strong>を中心に<strong class=\"source-bold\">ヒステリックな反共主義</strong>が高まり、<strong class=\"source-bold\">「<ruby>赤狩<rt>あかが</rt></ruby>り」</strong><ruby>旋風<rt>せんぷう</rt></ruby>（<strong class=\"source-bold\">マッカーシズム</strong>）が巻き起こった。例えば、リベラル派の人たちが「戦争反対！」って言っただけで「お前は共産主義者か！」と責められて公職を追放されたり、しまいには「トルーマンも共産主義者だ！」などと言い出す始</p>\n<blockquote><p>マッカーシズムでは、ハリウッドの俳優やメジャーリーガーまでもが「私は共産主義者じゃありません」と宣言させられたんだ</p></blockquote>",
  "375": "<h2>375</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ベルリン問題と冷戦体制の形成</u> 375</p></blockquote>\n<p>末。アメリカの反共アレルギーは、くるとこまできた感じだな……。</p>\n<p>イギリスでは、<strong class=\"source-bold\">労働党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アトリー</strong></span>政権が<strong class=\"source-bold\">「ゆりかごから墓場まで」</strong>をスローガンに失業保険・<ruby>疾病<rt>しっぺい</rt></ruby>保険・年金など<strong class=\"source-bold\">社会福祉制度の充実</strong>を図り、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">重要産業国有化</strong></span>などの<strong class=\"source-bold\">社会主義的な政策</strong>を進めたよ。ただ、冷戦が激しくなった1951年には保守党が総選挙で勝利し、<strong class=\"source-bold\">第2次チャーチル内閣</strong>が成立したんだ。</p>\n<p>フランスでは、大戦末期に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>を<ruby>首班<rt>しゅはん</rt></ruby>とする臨時政府ができて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第四共和政</strong></span>になった。そして戦後の議会選挙では<strong class=\"source-bold\">共産党</strong>や<strong class=\"source-bold\">社会党</strong>が<ruby>躍進<rt>やくしん</rt></ruby>し、右派と左派の連合政権になったから、ド＝ゴールは「共産党や社会党と一緒になど、やってられん！」と首相を辞めちゃった！。しかも、<strong class=\"source-bold\">マーシャル＝プラン受け入れ</strong>の問題から<strong class=\"source-bold\">共産党は政権から排除された</strong>んだ。だから、ド＝ゴール派と共産党の反対で政権が不安定になってしまったんだ。</p>\n<p>イタリアでは国民投票で<strong class=\"source-bold\">王政が廃止</strong>されて共和国になると、議会内では<strong class=\"source-bold\">共産党</strong>や<strong class=\"source-bold\">社会党</strong>が勢力を拡大して、反共路線をとる<strong class=\"source-bold\">キリスト教民主党</strong>と対立したよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 米ソ両国で<ruby>核<rt>かく</rt></ruby>開発競争が始まった！</strong></span></h4>\n<p>1945年に<strong class=\"source-bold\">アメリカ</strong>が<strong class=\"source-bold\">世界初</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">原子爆弾</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>原爆<rt>げんばく</rt></ruby></strong></span>】</strong>開発に成功したことで、核兵器を持つアメリカが軍事的には圧倒的に優位になった。これに対し、「核兵器の<ruby>脅威<rt>きょうい</rt></ruby>に対抗できるのは核兵器だけ」と思ったスターリンは核開発を急がせ、<strong class=\"source-bold\">ソ連</strong>では軍事部門最優先の<strong class=\"source-bold\">第4次五カ年計画</strong>が進められた。そして1949年には<strong class=\"source-bold\">原爆実験に成功</strong>、<strong class=\"source-bold\">ソ連が世界で2番目の核保有国</strong>になったんだ。</p>\n<blockquote><p>「アメリカの原爆保有→ソ連の原爆保有→アメリカの水爆保有→ソ連の水爆保有」の時代順は、よく出題されるよ！</p></blockquote>\n<p>対する<strong class=\"source-bold\">アメリカ</strong>は、まず1952年に再びチャーチルが首相となったイギリスに技術を提供して、<strong class=\"source-bold\">イギリスを核保有国</strong>にした。そして<strong class=\"source-bold\">アメリカ</strong>も同じ年の11月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">水素爆弾</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>水爆<rt>すいばく</rt></ruby></strong></span>】</strong>の実験に成功した。しかし、<strong class=\"source-bold\">ソ連</strong>もこれを追うように1953年には<strong class=\"source-bold\">水爆実験に成功</strong>したんだ。こんなふうに米ソ両国は「つねに相手を全滅できるだけの核兵器を持っていないと、相手の核兵器による攻撃は防げない」って考えて、核兵器の開発と保有数を競い始めたんだよ。ここは、「<strong class=\"source-bold\">原爆・水爆ともにアメリカが先</strong>に開発に成功して、それに<strong class=\"source-bold\">ソ連があとから追いついた</strong>」っていう順番をおさえておこう！</p>\n<p>そして、核開発競争の行き着く先は、<strong class=\"source-bold\">「核戦争が始まったら、米ソ両国だけではなく全人類・全世界が滅亡する」</strong>状態だ。つまり、相手に戦争を仕掛けたら自分も全滅する、だから戦争も起こせないし、核兵器も使えない。この考え方は<strong class=\"source-bold\">「核抑止力」</strong>と呼ばれている。そして、世界はお互いが相手の核戦力に恐れを抱く<strong class=\"source-bold\">「恐怖の<ruby>均衡<rt>きんこう</rt></ruby>」</strong>の時代に突入し、各国は米ソが自分の国を核兵器で守ってくれるかどうか（「核の傘」）、ってことを考えなきゃいけなくなったんだよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "376": "<h2>376</h2>\n<blockquote><p>376 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <strong class=\"source-bold\">アジアでの対立激化</strong></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">アジアでの対立激化</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">フランス</strong>の武力<ruby>介入<rt>かいにゅう</rt></ruby></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム民主共和国</strong></span>成立［1945.9］</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ戦争</strong></span>［1946〜］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>大韓<rt>だいかん</rt></ruby>民国</strong></span>独立［1948.8］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮民主主義人民共和国</strong></span>独立［1948.9］<br><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>成立［1949.10.1］<br><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ友好同盟相互援助条約</strong></span>［1950.2］<br>北朝鮮が韓国領内に<ruby>侵攻<rt>しんこう</rt></ruby></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮戦争</strong></span>［1950.6〜］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米軍主体の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連軍</strong></span>を派遣<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>米はアジアで軍事同盟を強化</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>中国は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民<ruby>義勇軍<rt>ぎゆうぐん</rt></ruby></strong></span>を派遣</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サンフランシスコ平和条約</strong></span>［1951.9］</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ベトナム、朝鮮、中国……アジアでも資本主義VS.社会主義が激化！</strong></span></h4>\n<p>ここで同じ時期の<strong class=\"source-bold\">アジア</strong>について見ておこう。ヨーロッパでは実際の戦争が起きない「<ruby>冷戦<rt>れいせん</rt></ruby>」だったけど、<strong class=\"source-bold\">アジアでは実際の戦争が起きてしまった</strong>んだよ。</p>\n<p>まず戦争になったのは<strong class=\"source-bold\">ベトナム</strong>だよ。日本の敗戦直後に、インドシナ共産党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホー＝チ＝ミン</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム民主共和国</strong></span>を建国し、<strong class=\"source-bold\">社会主義国</strong>として独立した。しかし、植民地支配の復活を狙う<strong class=\"source-bold\">フランスが武力介入</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ戦争</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>、フランスも南部に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バオダイ</strong></span>を主席とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム国</strong></span>を建てて対抗した。ここから1975年まで、ベトナムでは<strong class=\"source-bold\">社会主義の「北」</strong>と<strong class=\"source-bold\">資本主義の「南」</strong>の戦争が続くんだ。</p>\n<p><strong class=\"source-bold\">東アジア</strong>でも、<strong class=\"source-bold\">朝鮮</strong>と<strong class=\"source-bold\">中国</strong>で資本主義と社会主義が対立したよ。<strong class=\"source-bold\">カイロ宣言</strong>で日本からの独立を約束されていた朝鮮は、戦後は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北緯38度線</strong></span>を境界に<strong class=\"source-bold\">南をアメリカ</strong>が、<strong class=\"source-bold\">北をソ連</strong>がそれぞれ<ruby>占領<rt>せんりょう</rt></ruby>していたんだけど、ベルリン<ruby>封鎖<rt>ふうさ</rt></ruby>が始まって米ソ対立が激化すると、アメリカは朝鮮半島南部の独立を急ぎ、1948年8月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>李承晩<rt>イスンマン</rt></ruby></strong></span>を大統領とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大韓民国</strong></span>を成立させた。すると、ソ連も翌9月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>金日成<rt>キムイルソン</rt></ruby></strong></span>を<ruby>首班<rt>しゅはん</rt></ruby>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮民主主義人民共和国</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北朝鮮</strong></span>】</strong>を建て、<strong class=\"source-bold\">朝鮮半島の南北分断が確定</strong>したんだ。</p>\n<p>そして、東アジア情勢を大きく変えたのが<strong class=\"source-bold\">中国</strong>だよ。終戦直後には米ソ両国が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>蒋<rt>しょう</rt></ruby><ruby>介石<rt>かいせき</rt></ruby></strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華民国</strong></span>を正統な政府と認めたんだけど、蒋介石の<strong class=\"source-bold\">国民党</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>毛沢東<rt>もうたくとう</rt></ruby></strong></span>の<strong class=\"source-bold\">共産党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">内戦</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国共内戦</strong></span>）が始まり、国民党が徐々に追いつめられていった。そして、1949年には<strong class=\"source-bold\">内戦に勝利した共産党</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>の建国を宣言すると、敗れた<strong class=\"source-bold\">蒋介石は台湾に逃亡</strong>した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">台湾国民政府</strong></span>）。こうなると、資本主義と社会主義のバラ</p>",
  "377": "<h2>377</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アジアでの対立激化</u> 377</p></blockquote>\n<p>ンスが崩れる。これまでアメリカは、<strong class=\"source-bold\">蒋介石の国民政府を支援</strong>すれば東アジアの資本主義を守れると思っていたんだけど、共産党の勝利によって<strong class=\"source-bold\">一気に社会主義陣営が優勢</strong>になっちゃった。しかも、中華人民共和国とソ連が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ友好同盟相互援助条約</strong></span>を結んだから、東アジアでソ連の影響力が強まっていったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ついに朝鮮戦争が勃発！ こりゃ、米ソの代理戦争だ</strong></span></h4>\n<p>中華人民共和国が成立すると、北朝鮮の金日成は「これは半島を統一するチャンス！」って思った。だって、北朝鮮の背後がアメリカの支援する中華民国から、<strong class=\"source-bold\">ソ連と軍事同盟を結んだ中華人民共和国</strong>に変わったから、もう挟み撃ちになる心配はない！ こうして1950年6月、<strong class=\"source-bold\">北朝鮮軍</strong>が北緯38度線を越えて<strong class=\"source-bold\">韓国領内に攻め込み</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮戦争</strong></span>が勃発した！。そして、北朝鮮軍は一気に<ruby>釜山<rt>プサン</rt></ruby>まで<ruby>侵攻<rt>しんこう</rt></ruby>したんだ。</p>\n<h3><strong class=\"source-bold\">〈1950年9月〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">中華人民共和国</strong></td><td><strong class=\"source-bold\">朝鮮民主主義人民共和国</strong></td></tr><tr><td>平壌</td><td>北緯38度線</td></tr><tr><td>ソウル</td><td><strong class=\"source-bold\">大韓民国</strong></td></tr><tr><td>釜山</td><td></td></tr></tbody></table></div>\n<p>すぐさま<strong class=\"source-bold\">アメリカ</strong>は国連の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">緊急安全保障理事会</strong></span>を開き、北朝鮮軍を「<ruby>侵略者<rt>しんりゃくしゃ</rt></ruby>」として、<strong class=\"source-bold\">米軍主体</strong>の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連軍</strong></span>」の派遣を決めたんだ。ここで、ソ連が拒否権を使うのでは？ と思った人は鋭い！ この時<strong class=\"source-bold\">ソ連</strong>は、「中国の国連代表権を台湾が持っているのはおかしい」と抗議して、<strong class=\"source-bold\"><ruby>安保理<rt>あんぽり</rt></ruby>を欠席</strong>していたんだ。欠席すると「<ruby>棄権<rt>きけん</rt></ruby>」になるから、拒否権は使えない。ソ連が欠席すれば常任理事国は米・英・仏と<strong class=\"source-bold\">中華民国</strong>でしょ。ほら<strong class=\"source-bold\">資本主義国ばかり</strong>。だから、厳密に言うと、この軍隊は国連<ruby>憲章<rt>けんしょう</rt></ruby>にのっとった<strong class=\"source-bold\">正式な国連軍じゃない</strong>よ。</p>\n<p>こうして、「国連軍」は<strong class=\"source-bold\"><ruby>仁川<rt>インチョン</rt></ruby>上陸</strong>でソウルを奪還し、さらに<strong class=\"source-bold\">北上して中国国境に迫った</strong>から、今度は中国、そしてソ連が焦った！。ただ、名前だけとはいえ一応「国連軍」だから、これと戦うと表向きは全世界を敵に回したことになる……。だから<strong class=\"source-bold\">中国</strong>は「これ以上北上したら、<strong class=\"source-bold\">“中国人民”</strong>は見過ごさないだろう」と発表して「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民義勇軍</strong></span>」を送り込んだ。ていうか、<strong class=\"source-bold\">中身は中国軍</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民解放軍</strong></span>）だよ。しかも、この「義勇軍」には空軍もある……。一般人が戦闘機を持ってるわけないじゃん。この義勇軍は<strong class=\"source-bold\">ウラでソ連が支援</strong>してるんだよ。これで国連軍を後退させて<strong class=\"source-bold\"><ruby>平壌<rt>ピョンヤン</rt></ruby>を奪還</strong>し、さらに再びソウルを占領した。</p>\n<h3><strong class=\"source-bold\">〈1950年11月〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">中華人民共和国</strong></td><td>中国の人民義勇軍</td></tr><tr><td><strong class=\"source-bold\">朝鮮民主主義人民共和国</strong></td><td>平壌</td></tr><tr><td>国連軍 仁川上陸［1950.9］</td><td>北緯38度線</td></tr><tr><td>ソウル</td><td>仁川</td></tr><tr><td><strong class=\"source-bold\">大韓民国</strong></td><td></td></tr></tbody></table></div>\n<p>国連軍の総司令官<strong class=\"source-bold\">マッカーサー</strong>は、「中国の義勇軍</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "378": "<h2>378</h2>\n<blockquote><p>378 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p>をぶっ<ruby>潰<rt>つぶ</rt></ruby>すために、<strong class=\"source-bold\">中国へ<ruby>原爆<rt>げんばく</rt></ruby>攻撃をしたい</strong>」と言ったんだけど、これ以上戦争を拡大させたくない<strong class=\"source-bold\">トルーマン大統領に解任された</strong>よ。だって、朝鮮戦争は米ソが支援する<strong class=\"source-bold\">代理戦争</strong>になっちゃったから、戦争が拡大すると第三次世界大戦になりかねないでしょ。</p>\n<p>結局、1951年半ばには戦線が北緯38度線付近で<ruby>膠着<rt>こうちゃく</rt></ruby>状態になり、<strong class=\"source-bold\"><ruby>開城<rt>ケソン</rt></ruby>で休戦会談が始まった</strong>。その後、<strong class=\"source-bold\"><ruby>板<rt>パン</rt></ruby><ruby>門店<rt>ムンジョム</rt></ruby></strong>でおこなわれるようになった休戦交渉はなかなかまとまらなかったけど、1953年に<strong class=\"source-bold\">スターリンが死去</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北緯38度線</strong></span>付近を<strong class=\"source-bold\">軍事境界線</strong>にすることで合意すると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮休戦協定</strong></span>が調印された。ただ、<strong class=\"source-bold\">正式な<ruby>講和<rt>こうわ</rt></ruby>条約はいまだに結ばれてない</strong>から、法的には戦争が続いている状態のまま南北朝鮮の分断が固定され、ついに21世紀を迎えてしまったんだね。</p>\n<h3><strong class=\"source-bold\">〈1951年7月以降〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">中華人民共和国</strong></td><td>中国の人民義勇軍派遣</td></tr><tr><td><strong class=\"source-bold\">朝鮮民主主義人民共和国</strong></td><td>平壌</td></tr><tr><td>軍事境界線［1953.7］</td><td>北緯38度線</td></tr><tr><td>開城</td><td>板門店</td></tr><tr><td>ソウル</td><td><strong class=\"source-bold\">大韓民国</strong></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 朝鮮戦争を機に日本が独立！ さらに、アメリカはアジアで軍事同盟を強化</strong></span></h4>\n<p><strong class=\"source-bold\">朝鮮戦争</strong>はアメリカを焦らせたよ！。だって、中国が社会主義になったうえに、朝鮮半島まで社会主義にするわけにいかないでしょ。だから、<strong class=\"source-bold\">日本を<ruby>占領<rt>せんりょう</rt></ruby>している米軍を朝鮮半島に送りたかった</strong>んだ。そして日本を<strong class=\"source-bold\">「社会主義に対する<ruby>防壁<rt>ぼうへき</rt></ruby>」</strong>にするために、<strong class=\"source-bold\">日本経済の再建</strong>と<strong class=\"source-bold\">再軍備</strong>を進めることにした。こうして、マッカーサーの指令で<strong class=\"source-bold\">警察予備隊</strong>（のちの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自衛隊</strong></span>）が創設されたんだ。</p>\n<p>さらに1951年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サンフランシスコ平和条約</strong></span>が結ばれて<strong class=\"source-bold\">日本は独立を回復</strong>し、<strong class=\"source-bold\">資本主義陣営の一員</strong>になったけど、<strong class=\"source-bold\">ソ連などの共産圏の国々は条約に調印せず</strong>、インド・ビルマは条約案に不満だったので会議に参加せず、絶対に<ruby>揉<rt>も</rt></ruby>めるのがわかってるから<strong class=\"source-bold\">中華人民共和国と中華民国は招かれなかった</strong>ので、日本はこれらの国々と個別に<ruby>講和<rt>こうわ</rt></ruby>条約を結ばないといけなくなった。ただ独立とはいっても、<strong class=\"source-bold\"><ruby>沖縄<rt>おきなわ</rt></ruby>・<ruby>奄美<rt>あまみ</rt></ruby>と<ruby>小笠原<rt>おがさわら</rt></ruby>諸島</strong>は<ruby>暫定<rt>ざんてい</rt></ruby>的に<strong class=\"source-bold\">アメリカの軍政下</strong>に置かれ、さらにサンフランシスコ講和条約と同時に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日米安全保障条約</strong></span>が結ばれて、<strong class=\"source-bold\">日本はアメリカ軍に基地を提供</strong>することになった。これが今も続く米軍基地問題の<ruby>発端<rt>ほったん</rt></ruby>だね。</p>\n<blockquote><p>自衛隊や米軍基地の問題は、朝鮮戦争の時に、アメリカが日本を慌てて独立させたから起こったんだよ</p></blockquote>\n<p>そして<strong class=\"source-bold\">アメリカはアジアでも反共軍事同盟を強化</strong>したよ。ヨーロッパで<ruby>NATO<rt>ナトー</rt></ruby>をつくったみたいにアジアでも軍事同盟をつくって、<strong class=\"source-bold\">ソ連や中国</strong>、そして<strong class=\"source-bold\">北ベトナム</strong>を「<ruby>封<rt>ふう</rt></ruby>じ込め」ようってことだ。まず1951年に、フィリピンとの<strong class=\"source-bold\"><ruby>米比<rt>べいひ</rt></ruby>相互防衛条約</strong>を結び、さらに<strong class=\"source-bold\">オーストラリアとニュージーランド</strong>との反共軍事同盟である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">太平洋安全保障条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ANZUS<rt>アンザス</rt></ruby></strong></span>】</strong>をつくった。<strong class=\"source-bold\">ANZUSっていうの</strong></p>",
  "379": "<h2>379</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">「雪どけ」と「巻き返し政策」</u> 379</p></blockquote>\n<p><strong class=\"source-bold\">は3国の頭文字を取った略称</strong>だ。「A」はAustralia（オーストラリア）、「NZ」はNew Zealand（ニュージーランド）、「US」はUnited States（アメリカ合衆国）ね。この年には<strong class=\"source-bold\">日米安全保障条約も結ばれてる</strong>よ。さらに、1953年には朝鮮休戦協定に違反して<strong class=\"source-bold\"><ruby>米韓<rt>べいかん</rt></ruby>相互防衛条約</strong>を結び、<strong class=\"source-bold\">韓国軍の指揮権を在韓米軍が持つ</strong>ことになった。さらに台湾の中華民国とも<strong class=\"source-bold\"><ruby>米華<rt>べいか</rt></ruby>相互防衛条約</strong>を結んだよ。こうして、アジアも完全に<ruby>冷戦<rt>れいせん</rt></ruby>体制に組み込まれたんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <strong class=\"source-bold\">「雪どけ」と「巻き返し政策」</strong></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">「雪どけ」と「巻き返し政策」［1953〜55］</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アイゼンハワー</strong></span>大統領就任［1953.1］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリンの死</strong></span>［1953.3］</td></tr><tr><td>「<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">雪どけ</u>」</td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬅</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮休戦協定</strong></span>［1953.7］</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ休戦協定</strong></span>［1954.7］</td><td></td></tr><tr><td>「<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">巻き返し政策</u>」</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東南アジア条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SEATO<rt>シアトー</rt></ruby></strong></span>】</strong>［1954.9］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">パリ協定</strong>［1954.10］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">➡●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ドイツNATO加盟</strong></span>［1955.5］</td><td><span data-source-color=\"green\" style=\"color:#315837\">➡●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構</strong></span>成立［1955.5］</td></tr><tr><td><strong class=\"source-bold\">オーストリア国家条約</strong>［1955.5］</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ4巨頭会談</strong></span>［1955.7］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バグダード条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>METO<rt>メトー</rt></ruby></strong></span>】</strong>［1955.11］</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ スターリンが死去！ ソ連の態度が変化して「雪どけ」が始まった</strong></span></h4>\n<p>1953年、ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリンが死んだ</strong></span>！。こりゃ、ただ事じゃない。だって、ソ連の政策はスターリンが一人で決めてきたんだもん。そして、<strong class=\"source-bold\">反対したヤツはすべて<ruby>粛清<rt>しゅくせい</rt></ruby></strong>……。もはや、ソ連には微妙な人しか残っていない……。だって、スターリンより有能だと消されて、無能すぎても消される。スターリンにゴマをするヤツしか生き残れないけど、ゴマをすりすぎると「<ruby>胡散臭<rt>うさんくさ</rt></ruby>い」から消される……。</p>\n<p>結果的に、<strong class=\"source-bold\">スターリン死後のソ連には有力な後継者がいなかった</strong>から、個人<ruby>独裁<rt>どくさい</rt></ruby>じゃなくて<strong class=\"source-bold\">集団指導体制</strong>になった。そして、スターリンのような「アメリカと全面対決して、資本主義世界を全滅させる」といった主張が弱まり、<strong class=\"source-bold\">「米ソ間の話し合いで、対立を緩和</strong>させたほうがいいのでは……」という考え方が出てきて、米ソの和解ムードを生んだ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">雪どけ</strong></span>」だ。あっ！ <strong class=\"source-bold\">「雪どけ」はあくまでも「ムード」だけ</strong>だから、必ずしも本当に和解が進んだわけじゃないけど、今までの「全面</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "380": "<h2>380</h2>\n<blockquote><p>380 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p>対決」から「和解ムード」に変わったのは、大きな変化だよね。こうして、1953年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮休戦協定</strong></span>が結ばれ、さらに<strong class=\"source-bold\">インドシナ戦争</strong>の休戦会談も始まって、1954年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ休戦協定</strong></span>が結ばれた。ただ、<strong class=\"source-bold\">米ソ両国は「雪どけ」の裏側で対立</strong>を続けていたから、「雪どけ」だって手放しで喜んじゃダメだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アメリカではアイゼンハワー大統領が登場し、「巻き返し政策」が始まった！</strong></span></h4>\n<p>反共の嵐が吹き荒れる<strong class=\"source-bold\">アメリカ</strong>では、<strong class=\"source-bold\">共和党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アイゼンハワー</strong></span>が大統領になった。彼は第二次世界大戦の時には、<strong class=\"source-bold\">ノルマンディー上陸作戦の総司令官</strong>だったよね。そして<strong class=\"source-bold\">国務長官のダレス</strong>は、「トルーマン政権の“<ruby>封<rt>ふう</rt></ruby>じ込め政策”では甘い！ これからは積極的に<strong class=\"source-bold\">社会主義への反撃</strong>をするべきだ」として<strong class=\"source-bold\">「巻き返し政策」</strong>を始めたんだ。この時ダレスは、「もはや世界全体が社会主義になる“<ruby>瀬戸際<rt>せとぎわ</rt></ruby>”だ」として、<strong class=\"source-bold\">軍事同盟の強化</strong>と<strong class=\"source-bold\"><ruby>核<rt>かく</rt></ruby>兵器による大量報復</strong>を打ち出した（<strong class=\"source-bold\">“瀬戸際外交”</strong>）。</p>\n<p>こうして、<strong class=\"source-bold\">アメリカは軍事同盟をさらに強化</strong>した。まず、アジアでは太平洋安全保障条約<strong class=\"source-bold\">【</strong><ruby>ANZUS<rt>アンザス</rt></ruby><strong class=\"source-bold\">】</strong>、<ruby>米比<rt>べいひ</rt></ruby>相互防衛条約をもとにして、<strong class=\"source-bold\">ANZUSと英仏、フィリピン、タイ、パキスタン</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東南アジア条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SEATO<rt>シアトー</rt></ruby></strong></span>】</strong>を結成した。これは、ジュネーヴ休戦協定の<ruby>締結<rt>ていけつ</rt></ruby>を拒否した<strong class=\"source-bold\">アメリカがつくった北ベトナム<ruby>包囲網<rt>ほういもう</rt></ruby></strong>だ。さらに、ソ連に対する「巻き返し」として、ヨーロッパの反共軍事同盟を強化するために<strong class=\"source-bold\">西ドイツの再軍備</strong>に踏み切ったんだ。戦後、ドイツ軍は解散されたけど、考えてみれば、第二次世界大戦でヨーロッパ全体を敵にして戦った<strong class=\"source-bold\">ドイツの潜在的な軍事力はかなり強い</strong>！ しかも、西ドイツと東ドイツを比べると西ドイツのほうが強い。だったら西ドイツを反共同盟の一員にしちゃえばいい！ こうして1954年の<strong class=\"source-bold\">パリ協定</strong>では、<strong class=\"source-bold\">西ドイツの主権回復と再軍備</strong>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西ドイツの<ruby>NATO<rt>ナトー</rt></ruby>加盟</strong></span>が決まったんだ（加盟したのは1955年だよ）。そして、1955年には中東でも<strong class=\"source-bold\">英、トルコ、イラク、イラン、パキスタン</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バグダード条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>METO<rt>メトー</rt></ruby></strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中東条約機構</strong></span>】</strong>がつくられた。ただMETOは、アメリカによるイギリス連邦の切り崩しを警戒して、イギリス主導で結成されたんだけどね。これで、世界の反共軍事同盟が重なり合ってつながったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連もワルシャワ条約機構を結成！ 「雪どけ」で東西対話も実現！</strong></span></h4>\n<p>アメリカがソ連に対する「巻き返し政策」を進めたから、両陣営の緊張は高まった。<strong class=\"source-bold\">西ドイツのNATO加盟に対抗</strong>して、1955年、<strong class=\"source-bold\">ソ連</strong>も東欧の軍事同盟として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構</strong></span> <strong class=\"source-bold\">【</strong>東欧8カ国友好協力相互援助条約<strong class=\"source-bold\">】</strong>をつくった。加盟したのは<strong class=\"source-bold\">ソ連</strong>を中心に<strong class=\"source-bold\">ポーランド、東ドイツ、チェコスロヴァキア、ハンガリー、ルーマニア、ブルガリア、アルバニア</strong>の8カ国。<strong class=\"source-bold\">もちろん東ドイツも入っている</strong>からドイツは<ruby>冷戦<rt>れいせん</rt></ruby>の最前線になったんだ。これって、ソ連が「ドイツは1つ」から「2つのドイツ」に方針を転換したってことだ。あっ！ <strong class=\"source-bold\">独自路線のユーゴスラヴィアは入ってない</strong>けど、「雪どけ」ムードのなかで<strong class=\"source-bold\">ソ連とは和解</strong>したよ。これで米ソを中心とする軍事同盟が完成して、冷戦体制が確立したんだよ。</p>",
  "381": "<h2>381</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">5</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">「雪どけ」と「巻き返し政策」</u> 381</p></blockquote>\n<h3><strong class=\"source-bold\">〈東西両陣営の軍事同盟〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">北大西洋条約機構【NATO】［1949］</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ワルシャワ条約機構［1955］</strong></span></td></tr><tr><td>アイスランド<br>ノルウェー<br>デンマーク<br>西ドイツ（1955）</td><td><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">ポーランド</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">東ドイツ</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">チェコ</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">ハンガリー</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">ルーマニア</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">ブルガリア</span></td></tr><tr><td><strong class=\"source-bold\">米</strong></td><td><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span></td></tr><tr><td>英<br>仏<br>オランダ<br>ベルギー<br>ルクセンブルク</td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">中ソ友好同盟相互援助条約</strong></span></td></tr><tr><td><strong class=\"source-bold\">西ヨーロッパ連合条約</strong></td><td><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">中華人民共和国</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">北朝鮮</span><br><span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\">北ベトナム</span><br>南ベトナム</td></tr><tr><td>ポルトガル<br>伊<br>ギリシア</td><td>韓国<br><strong class=\"source-bold\"><ruby>米韓<rt>べいかん</rt></ruby>相互防衛条約</strong></td></tr><tr><td>トルコ<br>パキスタン<br>イラク<br>イラン</td><td>日本<br><strong class=\"source-bold\">日米安全保障条約</strong></td></tr><tr><td><strong class=\"source-bold\">バグダード条約機構【METO】</strong></td><td>中華民国<br><strong class=\"source-bold\"><ruby>米華<rt>べいか</rt></ruby>相互防衛条約</strong></td></tr><tr><td>タイ<br>フィリピン<br>オーストラリア<br>ニュージーランド</td><td><strong class=\"source-bold\"><ruby>米比<rt>べいひ</rt></ruby>相互防衛条約</strong></td></tr><tr><td><strong class=\"source-bold\">東南アジア条約機構【SEATO】</strong></td><td><strong class=\"source-bold\">太平洋安全保障条約【ANZUS】</strong><br><strong class=\"source-bold\">米</strong></td></tr></tbody></table></div>\n<p>とはいえ、「雪どけ」ムードがないわけじゃない。ベルリン問題や東西ドイツなど、根本的な問題が解決したわけではないけど、両陣営が「とりあえず話し合っておこう」と考えて、<strong class=\"source-bold\">対立が緩和された部分もある</strong>よ。まず、1955年5月には<strong class=\"source-bold\">オーストリア国家条約</strong>が結ばれて<strong class=\"source-bold\">4国の共同管理が解消</strong>され、<strong class=\"source-bold\">1つの国として独立を回復</strong>したよ。分断国家が増えなくてよかったね。そしてオーストリアは両陣営どちらにも味方しない<strong class=\"source-bold\">永世中立国</strong>になった。さらに7月には、ジュネーヴで<strong class=\"source-bold\">米英仏ソ4国の首脳会談</strong>が実現したよ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ4巨頭会談</strong></span>に参加したのは、アメリカ大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アイゼンハワー</strong></span>、ソ連首相<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガーニン</strong></span>、イギリス首相<strong class=\"source-bold\">イーデン</strong>、フランス首相<strong class=\"source-bold\">フォール</strong>の4人だよ。<strong class=\"source-bold\">この会議で決まったことは……何もない</strong>。根本的な問題は何も解決できなかったんだよ。そうはいっても、4国首脳が話し合いのテーブルについただけでも一歩前進だ。話し合うことに意義がある！ってことだよ。</p>\n<p>では、なんで東西の主要国の首脳が集まったんだろう？ これは、同じ年に開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1回アジア・アフリカ会議</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バンドン会議</strong></span>】</strong> <span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.438</span>に対抗するためだ！。第1回アジア・アフリカ会議では、その前年にインドの<strong class=\"source-bold\">ネルー</strong>と中華人民共和国の<strong class=\"source-bold\"><ruby>周恩来<rt>しゅうおんらい</rt></ruby></strong>の会談で発表された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和五原則</strong></span>をもとに、<strong class=\"source-bold\">平和共存や反植民地主義、人種と国家間の平等</strong>などを<ruby>謳<rt>うた</rt></ruby>った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和十原則</strong></span>を<ruby>採択<rt>さいたく</rt></ruby>して、各国の植民地での独立運動に影響を与えていたからね。しかも、ここに集まった<strong class=\"source-bold\">新興独立国は非同盟中立を掲げて、米ソが主導する東西対立から距離を置こうとしていた</strong>んだ。だから「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第三世</strong></span></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "382": "<h2>382</h2>\n<blockquote><p>382 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第20回</strong></span> 冷戦の展開①（1945〜1955）</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">界</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第三勢力</strong></span>】</strong>」って呼ばれるよ。こうした動きに対抗するために、米英仏ソの首脳が集まってジュネーヴ4巨頭会談が開かれたんだよ。</p>\n<p>そして……冷戦の最前線にされちゃった<strong class=\"source-bold\">ドイツ</strong>は、<strong class=\"source-bold\">「同じ民族同士の戦争はしたくない！」</strong>って思ったんだ。だって、もし東西の戦争が起きたら、最初に衝突するのは「西ドイツvs.東ドイツ」になっちゃうでしょ。だから、戦争を起こしちゃマズい……。そこで<strong class=\"source-bold\">西ドイツ</strong>は、ソ連との関係改善を目指したんだよ。結果、9月には<strong class=\"source-bold\">ソ連と西ドイツが国交回復</strong>を実現したよ。もちろん、<strong class=\"source-bold\">領土問題、ベルリン問題などにはあえて触れない</strong>。だって、触れた瞬間ケンカになるでしょ。まずは、対話を一歩ずつ進めるのが先だよ。</p>\n<p>こんなふうに1955年には、<strong class=\"source-bold\">両陣営の軍事同盟が完成</strong>して対立が鮮明になる一方で、両陣営の勢力圏が確定したことで、オーストリア国家条約やジュネーヴ4巨頭会談など<strong class=\"source-bold\">「雪どけ」</strong>も進んだんだ。</p>\n<p>じゃあ、今回はここまでだよ。最後に年号check！</p>\n<h3><strong class=\"source-bold\">‼</strong> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><em>年号のツボ</em></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">トルーマン＝ドクトリン</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1947</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>し<rt>4</rt></ruby></strong></span>か<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>な<rt>7</rt></ruby></strong></span>かった トルコとギリシア）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ベルリン<ruby>封鎖<rt>ふうさ</rt></ruby></strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1948</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひ<rt>1</rt></ruby>ど<ruby>く<rt>9</rt></ruby><ruby>弱<rt>48</rt></ruby></strong></span>った ベルリン市民）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>NATO<rt>ナトー</rt></ruby> 成立</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1949</strong></span>］（NATOが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>く<rt>9</rt></ruby><ruby>じ<rt>4</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span> 社会主義）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">朝鮮戦争<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1950</strong></span>］（朝鮮戦争 <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひ<rt>1</rt></ruby><ruby>ど<rt>9</rt></ruby><ruby>く<rt>5</rt></ruby><ruby>困<rt>0</rt></ruby>る</strong></span>）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">スターリンの死</strong>［19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">53</strong></span>］（死後の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>誤<rt>5</rt></ruby><ruby>算<rt>3</rt></ruby></strong></span>は 「雪どけ」だ）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ワルシャワ条約機構樹立</strong>［19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">55</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>今<rt>5</rt></ruby><ruby>後<rt>5</rt></ruby></strong></span>は反撃 東欧諸国）</p></blockquote>\n<p>次回は引き続き<ruby>冷戦<rt>れいせん</rt></ruby>の展開だよ。<strong class=\"source-bold\">米ソ対立</strong>が鮮明になる一方で、対話ムードの<strong class=\"source-bold\">「雪どけ」</strong>も進んで……世界はいったいどっちに向かうんだろう？ お楽しみに！</p>",
  "383": "<h2>383</h2>\n<blockquote><p>383</p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">7</span></h3>\n<h4><strong class=\"source-bold\">〜占領から主権回復・55年体制の形成〜</strong></h4>\n<blockquote><p>第二次世界大戦後、敗戦国となった日本は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">GHQ</strong></span>のもとに置かれて、<strong class=\"source-bold\">実質的にはアメリカ軍の単独占領</strong>になったけど、<strong class=\"source-bold\">南西諸島（<ruby>沖縄<rt>おきなわ</rt></ruby>・<ruby>奄美<rt>あまみ</rt></ruby>）と<ruby>小笠原<rt>おがさわら</rt></ruby>諸島はアメリカ軍の直接<ruby>統治<rt>とうち</rt></ruby>下</strong>に置かれたんだ。GHQの間接統治下では非軍事化や民主化が進められ、本文で書いたことのほかに、<strong class=\"source-bold\">女性参政権</strong>の付与や、日本国憲法に基づいて、<strong class=\"source-bold\">地方自治法</strong>や<strong class=\"source-bold\">教育基本法</strong>の制定や、民法の改正によって<strong class=\"source-bold\">男女同権の家族制度</strong>が定められたんだ。また、<strong class=\"source-bold\">政党政治も復活</strong>して、戦前の二大政党の流れをくむ勢力は日本自由党や進歩党（のちの民主党）をつくり、1946年には日本自由党が第1党となって第1次<strong class=\"source-bold\"><ruby>吉田茂<rt>よしだしげる</rt></ruby></strong>内閣ができたんだ。</p>\n<p>一方で、戦後の物資不足で国民の生活はむちゃくちゃ貧しかったから、<strong class=\"source-bold\">社会主義体制の実現を目指す革新勢力も現れ</strong>、「米よこせ！」と訴える食糧メーデーや、ゼネラル＝ストライキなどの労働運動も活発になった。ただ、世界は資本主義陣営と社会主義陣営が対立する冷戦の時代だからね。GHQはこうした社会主義的な運動を中止させたんだ。こうしたことも影響して、1947年の衆議院選挙では<strong class=\"source-bold\">日本社会党</strong>が躍進し、新憲法のもとでの最初の首相指名では<strong class=\"source-bold\">社会党の<ruby>片<rt>かた</rt></ruby><ruby>山哲<rt>やまてつ</rt></ruby></strong>が選ばれ、民主党・国民協同党との連立内閣ができたんだ！。</p>\n<p>その後、朝鮮半島の分断や中国での国共内戦激化など、アジアでも冷戦が表面化し始めると、絶対に共産主義を拡大させたくないアメリカは、1948年、日本の占領政策を「非軍事化と民主化」から<strong class=\"source-bold\">「経済<ruby>復興<rt>ふっこう</rt></ruby>と自立的な国家建設」</strong>に変えて、<ruby>財閥解体<rt>ざいばつかいたい</rt></ruby>の緩和や公務員の労働争議の禁止などを決めた。さらに、<strong class=\"source-bold\">官公庁などから共産主義者を追放</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レッドパージ</strong></span>がおこなわれる一方で、日本経済を国際経済に復帰させるため、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1ドル＝360円の単一為替レート</strong></span>が設定され、国際通貨基金<strong class=\"source-bold\">【</strong>IMF<strong class=\"source-bold\">】</strong>加盟の準備が進められた。</p>\n<p>1950年に朝鮮戦争が勃発すると、アメリカ軍向け物資の需要などのいわゆる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮<ruby>特需<rt>とくじゅ</rt></ruby></strong></span>で日本経済は復興に向かったんだ。そして1951年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">吉田茂</strong></span>内閣が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サンフランシスコ平和条約</strong></span>を結んで、日本は主権を回復したけど、同時に結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日米安全保障条約</strong></span>で、独立後もアメリカ軍が日本国内の基地に駐留することとなり、日本は西側陣営の一員に組み込まれた。</p>\n<p>このため、日本の国内政治では<strong class=\"source-bold\">アメリカの方針を支持する保守勢力</strong>と、<strong class=\"source-bold\">それを批判する革新勢力</strong>とが対立した。1955年、社会党が「非武装中立」を唱えて統一すると、保守勢力の<strong class=\"source-bold\">自由党と民主党がアメリカや財界の後押し</strong>で<ruby>合併<rt>がっぺい</rt></ruby>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>自由民<rt>じゆうみん</rt></ruby><ruby>主党<rt>しゅとう</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自民党</strong></span>】</strong>を結成した。以後、自民党が政権を取り続け、それに野党第1党の<strong class=\"source-bold\">社会党</strong>が労働組合の支持を得て対抗する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">55年体制</strong></span>が38年間も続いたよ。</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>"
};

